<?php
/** AI agents: workflows vs agents, the agent loop, tool design, MCP, safety and evaluation, context and memory, multi-agent systems, MCP transports and resources. */

if (!function_exists('fig_agents_compare')) {
    function fig_agents_compare(string $wf, string $wfn, string $s1, string $s2, string $s3, string $ag, string $agn, string $model, string $tools, string $act, string $obs, string $done): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 300" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><defs><marker id="wa" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#1E1C52"/></marker></defs><rect x="10" y="10" width="300" height="280" rx="14" fill="#FFFFFF" stroke="#8A87B0" stroke-width="2"/><rect x="330" y="10" width="300" height="280" rx="14" fill="#FFFFFF" stroke="#8A87B0" stroke-width="2"/><text x="30" y="40" font-weight="700">{$wf}</text><text x="30" y="60" font-size="13" fill="#5E5B85">{$wfn}</text><text x="350" y="40" font-weight="700">{$ag}</text><text x="350" y="60" font-size="13" fill="#5E5B85">{$agn}</text><rect x="70" y="82" width="180" height="44" rx="10" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="160.0" y="109.0" text-anchor="middle" font-size="13" font-weight="700" fill="#1B66BC">{$s1}</text><line x1="160" y1="128" x2="160" y2="146" stroke="#1E1C52" stroke-width="2" marker-end="url(#wa)"/><rect x="70" y="150" width="180" height="44" rx="10" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="160.0" y="177.0" text-anchor="middle" font-size="13" font-weight="700" fill="#1B66BC">{$s2}</text><line x1="160" y1="196" x2="160" y2="214" stroke="#1E1C52" stroke-width="2" marker-end="url(#wa)"/><rect x="70" y="218" width="180" height="44" rx="10" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="160.0" y="245.0" text-anchor="middle" font-size="13" font-weight="700" fill="#1B66BC">{$s3}</text><rect x="400" y="90" width="160" height="50" rx="10" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="480.0" y="120.0" text-anchor="middle" font-size="13" font-weight="700" fill="#5A35D0">{$model}</text><path d="M560 115 C 620 115, 620 210, 560 210" fill="none" stroke="#1E1C52" stroke-width="2" marker-end="url(#wa)"/><path d="M400 210 C 340 210, 340 115, 398 115" fill="none" stroke="#1E1C52" stroke-width="2" marker-end="url(#wa)"/><rect x="400" y="186" width="160" height="50" rx="10" fill="#FFE8D6" stroke="#E8590C" stroke-width="2"/><text x="480.0" y="216.0" text-anchor="middle" font-size="13" font-weight="700" fill="#B84508">{$tools}</text><text x="590" y="166" font-size="13" text-anchor="end">{$act}</text><text x="370" y="166" font-size="13">{$obs}</text><line x1="480" y1="238" x2="480" y2="262" stroke="#0B7F5C" stroke-width="2" marker-end="url(#wa)"/><text x="490" y="280" font-size="13" font-weight="700" fill="#0B7F5C">{$done}</text></svg>
SVG;
    }
}

if (!function_exists('fig_agents_loop')) {
    function fig_agents_loop(string $ctx, string $ctxn, string $think, string $thinkd, string $act, string $actd, string $obs, string $obsd, string $stop, string $stopd, string $limit): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 330" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><style>.ag{transform-origin:300px 165px;animation:agspin 9s linear infinite}@keyframes agspin{to{transform:rotate(360deg)}}@media (prefers-reduced-motion:reduce){.ag{animation:none}}</style><defs><marker id="al" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#0B7F5C"/></marker></defs><circle cx="300" cy="165" r="115" fill="none" stroke="#8A87B0" stroke-width="2" stroke-dasharray="6 6"/><rect x="230" y="135" width="140" height="60" rx="12" fill="#F1F0F8" stroke="#8A87B0" stroke-width="2"/><text x="300" y="159" text-anchor="middle" font-size="13" font-weight="700">{$ctx}</text><text x="300" y="179" text-anchor="middle" font-size="13" fill="#5E5B85">{$ctxn}</text><rect x="220" y="22" width="160" height="56" rx="12" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="300" y="44" text-anchor="middle" font-weight="700" fill="#5A35D0">{$think}</text><text x="300" y="64" text-anchor="middle" font-size="13">{$thinkd}</text><rect x="320.1" y="194.5" width="160" height="56" rx="12" fill="#FFE8D6" stroke="#E8590C" stroke-width="2"/><text x="400.1" y="216.5" text-anchor="middle" font-weight="700" fill="#B84508">{$act}</text><text x="400.1" y="236.5" text-anchor="middle" font-size="13">{$actd}</text><rect x="119.9" y="194.5" width="160" height="56" rx="12" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="199.9" y="216.5" text-anchor="middle" font-weight="700" fill="#1B66BC">{$obs}</text><text x="199.9" y="236.5" text-anchor="middle" font-size="13">{$obsd}</text><g class="ag"><circle cx="400.1" cy="107.5" r="8" fill="#E8590C"/></g><line x1="380" y1="50" x2="520" y2="50" stroke="#0B7F5C" stroke-width="2" marker-end="url(#al)"/><rect x="524" y="24" width="106" height="52" rx="12" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="577" y="46" text-anchor="middle" font-size="13" font-weight="700" fill="#0B7F5C">{$stop}</text><text x="577" y="64" text-anchor="middle" font-size="12" fill="#0B7F5C">{$stopd}</text><text x="20" y="318" font-size="13" fill="#5E5B85">{$limit}</text></svg>
SVG;
    }
}

if (!function_exists('fig_agents_mcp')) {
    function fig_agents_mcp(string $host, string $hostn, string $c1, string $c1n, string $c2, string $c2n, string $c3, string $c3n, string $note): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 300" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><rect x="20" y="90" width="200" height="120" rx="14" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="120" y="122" text-anchor="middle" font-weight="700" fill="#5A35D0">{$host}</text><text x="120" y="144" text-anchor="middle" font-size="13">{$hostn}</text><rect x="400" y="24" width="220" height="72" rx="12" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="414" y="52" font-weight="700" fill="#0B7F5C">MCP server: {$c1}</text><text x="414" y="76" font-size="13">{$c1n}</text><line x1="222" y1="128" x2="398" y2="60" stroke="#0B7F5C" stroke-width="2"/><circle cx="222" cy="128" r="4" fill="#0B7F5C"/><rect x="400" y="114" width="220" height="72" rx="12" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="414" y="142" font-weight="700" fill="#0B7F5C">MCP server: {$c2}</text><text x="414" y="166" font-size="13">{$c2n}</text><line x1="222" y1="150" x2="398" y2="150" stroke="#0B7F5C" stroke-width="2"/><circle cx="222" cy="150" r="4" fill="#0B7F5C"/><rect x="400" y="204" width="220" height="72" rx="12" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="414" y="232" font-weight="700" fill="#0B7F5C">MCP server: {$c3}</text><text x="414" y="256" font-size="13">{$c3n}</text><line x1="222" y1="172" x2="398" y2="240" stroke="#0B7F5C" stroke-width="2"/><circle cx="222" cy="172" r="4" fill="#0B7F5C"/><rect x="70" y="164" width="100" height="30" rx="8" fill="#FFFFFF" stroke="#7048E8" stroke-width="2"/><text x="120" y="184" text-anchor="middle" font-size="13">MCP client</text><text x="310" y="290" text-anchor="middle" font-size="13" fill="#5E5B85">{$note}</text></svg>
SVG;
    }
}

if (!function_exists('fig_agents_multi')) {
    function fig_agents_multi(string $orch, string $sub, string $own, string $reads, string $merge, string $split): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 320" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><defs><marker id="ma" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#1E1C52"/></marker></defs><rect x="220" y="20" width="200" height="50" rx="10" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><text x="320.0" y="50.0" text-anchor="middle" font-size="13" font-weight="700" fill="#5A35D0">{$orch}</text><rect x="20" y="130" width="190" height="96" rx="12" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="115" y="156" text-anchor="middle" font-weight="700" fill="#1B66BC">{$sub} 1</text><text x="115" y="178" text-anchor="middle" font-size="13">{$own}</text><text x="115" y="200" text-anchor="middle" font-size="13">{$reads}</text><line x1="270" y1="72" x2="103" y2="126" stroke="#1E1C52" stroke-width="2" marker-end="url(#ma)"/><line x1="127" y1="228" x2="127" y2="256" stroke="#0B7F5C" stroke-width="2"/><rect x="230" y="130" width="190" height="96" rx="12" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="325" y="156" text-anchor="middle" font-weight="700" fill="#1B66BC">{$sub} 2</text><text x="325" y="178" text-anchor="middle" font-size="13">{$own}</text><text x="325" y="200" text-anchor="middle" font-size="13">{$reads}</text><line x1="300" y1="72" x2="313" y2="126" stroke="#1E1C52" stroke-width="2" marker-end="url(#ma)"/><line x1="337" y1="228" x2="337" y2="256" stroke="#0B7F5C" stroke-width="2"/><rect x="440" y="130" width="190" height="96" rx="12" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="535" y="156" text-anchor="middle" font-weight="700" fill="#1B66BC">{$sub} 3</text><text x="535" y="178" text-anchor="middle" font-size="13">{$own}</text><text x="535" y="200" text-anchor="middle" font-size="13">{$reads}</text><line x1="330" y1="72" x2="523" y2="126" stroke="#1E1C52" stroke-width="2" marker-end="url(#ma)"/><line x1="547" y1="228" x2="547" y2="256" stroke="#0B7F5C" stroke-width="2"/><path d="M127 256 H547" stroke="#0B7F5C" stroke-width="2"/><line x1="320" y1="256" x2="320" y2="274" stroke="#0B7F5C" stroke-width="2" marker-end="url(#ma)"/><rect x="200" y="278" width="240" height="36" rx="10" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="320.0" y="301.0" text-anchor="middle" font-size="13" font-weight="700" fill="#0B7F5C">{$merge}</text><text x="20" y="100" font-size="13" fill="#5E5B85">{$split}</text></svg>
SVG;
    }
}

return [
    'id' => 'ai-agents', 'family' => 'llm', 'after' => 'llm-api',
    'title' => L('Agenti AI e MCP', 'AI Agents and MCP'), 'short' => L('Agenti AI', 'AI Agents'), 'level' => L('Avanzato', 'Advanced'),
    'desc' => L('Modelli che agiscono: flussi o agenti, il ciclo agentico, progettare gli strumenti, il Model Context Protocol, sicurezza e valutazione, contesto e memoria, sistemi multi-agente, MCP in pratica.', 'Models that act: workflows or agents, the agent loop, designing tools, the Model Context Protocol, safety and evaluation, context and memory, multi-agent systems, MCP in practice.'),
    'lessons' => [
        lesson('what', L('Flussi e agenti', 'Workflows and agents'), [
            P('Un **flusso** (workflow) è una sequenza di passi decisa dal tuo codice: “estrai, poi classifica, poi scrivi”. Un **agente** invece decide da solo quali strumenti usare e quando fermarsi, in un ciclo, per raggiungere un obiettivo.', 'A **workflow** is a sequence of steps decided by your code: “extract, then classify, then write”. An **agent** instead decides by itself which tools to use and when to stop, in a loop, to reach a goal.'),
            P('Gli agenti sono potenti per compiti aperti e difficili da prevedere (correggere un bug in un progetto, fare una ricerca), ma costano di più, sono più lenti e più difficili da controllare. Regola pratica: parti dalla soluzione **più semplice** (una chiamata, poi un flusso) e passa all’agente solo se serve davvero.', 'Agents are powerful for open-ended, hard-to-predict tasks (fixing a bug in a project, doing research), but they cost more, are slower and harder to control. Rule of thumb: start with the **simplest** solution (one call, then a workflow) and move to an agent only when you truly need one.'),
            Fig(L(fig_agents_compare('Workflow', 'il percorso lo decide il tuo codice', 'estrai', 'classifica', 'scrivi', 'Agente', 'il percorso lo decide il modello', 'modello', 'strumenti', 'agisce', 'osserva', 'risposta finale'), fig_agents_compare('Workflow', 'your code decides the path', 'extract', 'classify', 'write', 'Agent', 'the model decides the path', 'model', 'tools', 'acts', 'observes', 'final answer')),
                L('Due pannelli. A sinistra un workflow: tre passi fissi in colonna, estrai, classifica, scrivi. A destra un agente: il modello e gli strumenti collegati in un ciclo, agisce e osserva, finché esce con la risposta finale.', 'Two panels. On the left a workflow: three fixed steps in a column, extract, classify, write. On the right an agent: the model and the tools linked in a loop, acting and observing, until it leaves with the final answer.'),
                L('Workflow: strada fissa. Agente: un ciclo di cui non sai in anticipo la lunghezza.', 'Workflow: a fixed road. Agent: a loop whose length you do not know in advance.')),
        ], [
            Q('w1', L('Chi decide i passi in un workflow?', 'Who decides the steps in a workflow?'), [L('Il tuo codice', 'Your code'), L('Il modello', 'The model'), L('L’utente a ogni passo', 'The user at each step'), L('Nessuno', 'Nobody')], 0, L('Nell’agente li decide il modello.', 'In an agent the model decides.')),
            Q('w2', L('Quando ha senso un agente?', 'When does an agent make sense?'), [L('Per compiti aperti e difficili da prevedere', 'For open-ended, hard-to-predict tasks'), L('Per tradurre una parola', 'To translate one word'), L('Sempre', 'Always'), L('Mai', 'Never')], 0, L('Altrimenti basta un flusso.', 'Otherwise a workflow is enough.')),
            Q('w3', L('Da dove conviene partire?', 'Where should you start?'), [L('Dalla soluzione più semplice', 'From the simplest solution'), L('Dall’agente più complesso', 'From the most complex agent'), L('Da dieci agenti insieme', 'From ten agents at once'), L('Dal fine-tuning', 'From fine-tuning')], 0, L('Complessità solo se serve.', 'Complexity only when needed.')),
        ], task('text', L('Per ciascun compito scrivi `flusso` o `agente`, uno per riga come `compito: scelta`. Compiti: `tradurre 1000 descrizioni prodotto`, `correggere un bug sconosciuto in un repository`.', 'For each task write `workflow` or `agent`, one per line as `task: choice`. Tasks: `translate 1000 product descriptions`, `fix an unknown bug in a repository`.'), '', [re('(tradurre|translate)[^:\n]*:\s*(flusso|workflow)', L('La traduzione in serie è un flusso', 'Bulk translation is a workflow')), re('(bug)[^:\n]*:\s*(agente|agent)', L('Il bug sconosciuto richiede un agente', 'The unknown bug needs an agent'))], '', "tradurre 1000 descrizioni prodotto: flusso\ncorreggere un bug sconosciuto in un repository: agente"), [
            dMatch(pMatch(), [[L('Una chiamata', 'One call'), L('Compiti semplici', 'Simple tasks')], [L('Flusso', 'Workflow'), L('Passi decisi dal codice', 'Steps decided by code')], [L('Agente', 'Agent'), L('Il modello sceglie gli strumenti', 'The model picks the tools')], [L('Costo', 'Cost'), L('Cresce con l’autonomia', 'Grows with autonomy')]], L('Scegliere il livello giusto.', 'Picking the right level.')),
            dFlash(pFlash(), [[L('Un agente decide quando fermarsi', 'An agent decides when to stop'), true], [L('Gli agenti sono sempre più economici', 'Agents are always cheaper'), false], [L('Un flusso ha passi decisi dal codice', 'A workflow has code-decided steps'), true], [L('Ogni problema richiede un agente', 'Every problem needs an agent'), false]], L('Semplice prima, autonomo poi.', 'Simple first, autonomous later.')),
        ]),
        lesson('loop', L('Il ciclo agentico', 'The agent loop'), [
            P('Un agente è un ciclo: mandi al modello obiettivo, storia e strumenti; se chiede uno strumento lo esegui e rimandi il risultato; ripeti finché il modello risponde senza chiedere altro. Serve sempre un **limite** di passi o di spesa.', 'An agent is a loop: send the model goal, history and tools; if it asks for a tool, run it and send back the result; repeat until the model answers without asking for more. You always need a **limit** on steps or spending.'),
            Fig(L(fig_agents_loop('contesto', 'obiettivo + storia', 'Pensa', 'quale strumento?', 'Agisci', 'chiama lo strumento', 'Osserva', 'legge il risultato', 'Fine', 'nessun tool_use', 'Un limite di passi o di spesa ferma il ciclo anche se il modello non si ferma da solo.'), fig_agents_loop('context', 'goal + history', 'Think', 'which tool?', 'Act', 'calls the tool', 'Observe', 'reads the result', 'Stop', 'no tool_use', 'A step or spending limit stops the loop even when the model does not stop by itself.')),
                L('Un ciclo di tre riquadri attorno al contesto (obiettivo e storia): pensa quale strumento usare, agisci chiamandolo, osserva il risultato, e di nuovo pensa; un pallino gira lungo il cerchio. Dal riquadro «pensa» esce una freccia verso «fine», quando il modello risponde senza chiedere strumenti.', 'A cycle of three boxes around the context (goal and history): think about which tool to use, act by calling it, observe the result, and think again; a dot goes round the circle. From the “think” box an arrow leads to “stop”, when the model answers without asking for tools.'),
                L('Ogni giro aggiunge al contesto ciò che l’agente ha visto.', 'Each round adds what the agent has seen to the context.')),
            C('messaggi = [{"role": "user", "content": obiettivo}]
for passo in range(20):                       # limite di sicurezza
    r = client.messages.create(model="claude-opus-5-5", max_tokens=4096,
                               tools=strumenti, messages=messaggi)
    messaggi.append({"role": "assistant", "content": r.content})
    if r.stop_reason != "tool_use":
        break                                 # risposta finale
    risultati = [{"type": "tool_result", "tool_use_id": b.id, "content": esegui(b.name, b.input)}
                 for b in r.content if b.type == "tool_use"]
    messaggi.append({"role": "user", "content": risultati})', 'python'),
            P('Il modello può chiedere più strumenti nello stesso turno: si eseguono tutti e si rimandano tutti i risultati in un solo messaggio. Gli SDK offrono anche helper che gestiscono il ciclo al posto tuo.', 'The model can ask for several tools in the same turn: run them all and send all the results back in one message. SDKs also offer helpers that run the loop for you.'),
        ], [
            Q('l1', L('Quando finisce il ciclo?', 'When does the loop end?'), [L('Quando il modello non chiede più strumenti', 'When the model stops asking for tools'), L('Dopo un passo, sempre', 'After one step, always'), L('Mai', 'Never'), L('Quando l’utente spegne il PC', 'When the user turns off the PC')], 0, L('O quando scatta il limite.', 'Or when the limit trips.')),
            Q('l2', L('Perché serve un limite di passi?', 'Why do you need a step limit?'), [L('Per evitare cicli infiniti e spese', 'To avoid endless loops and spending'), L('Per far contento il modello', 'To please the model'), L('Non serve', 'It is not needed'), L('Per l’estetica', 'For looks')], 0, L('Sicurezza prima di tutto.', 'Safety first.')),
            Q('l3', L('Come rimandi più risultati di strumenti?', 'How do you send back several tool results?'), [L('Tutti insieme in un solo messaggio', 'All together in one message'), L('Uno per chiamata separata', 'One per separate call'), L('Non si rimandano', 'You do not'), L('Solo il primo', 'Only the first')], 0, L('Ognuno con il suo tool_use_id.', 'Each with its tool_use_id.')),
        ], task('python', L('Completa il ciclo: esci con `break` quando `r.stop_reason` è diverso da `"tool_use"`.', 'Complete the loop: exit with `break` when `r.stop_reason` differs from `"tool_use"`.'), "for passo in range(20):\n    r = client.messages.create(model=\"claude-opus-5-5\", max_tokens=4096, tools=strumenti, messages=messaggi)\n    messaggi.append({\"role\": \"assistant\", \"content\": r.content})\n    ", [re('if\s+r\.stop_reason\s*!=\s*["\']tool_use["\']\s*:\s*\n\s+break', L('Esci alla risposta finale', 'You exit at the final answer')), re('for\s+passo\s+in\s+range\s*\(\s*20\s*\)', L('C’è il limite di passi', 'The step limit is there'))], '', "for passo in range(20):\n    r = client.messages.create(model=\"claude-opus-5-5\", max_tokens=4096, tools=strumenti, messages=messaggi)\n    messaggi.append({\"role\": \"assistant\", \"content\": r.content})\n    if r.stop_reason != \"tool_use\":\n        break"), [
            dOrder(pSort(), [L('Invia obiettivo e strumenti', 'Send goal and tools'), L('Il modello chiede uno strumento', 'The model asks for a tool'), L('Esegui lo strumento', 'Run the tool'), L('Rimanda il risultato', 'Send back the result'), L('Ripeti finché arriva la risposta finale', 'Repeat until the final answer')], L('Il cuore di un agente.', 'The heart of an agent.')),
            dBug(pBug(), ['while True:', '    r = client.messages.create(model=M, max_tokens=4096, tools=T, messages=msgs)', '    if r.stop_reason != "tool_use":', '        break'], 0, 'for passo in range(20):', L('Senza limite il ciclo può non finire mai.', 'Without a limit the loop may never end.')),
        ]),
        lesson('tools', L('Progettare gli strumenti', 'Designing tools'), [
            P('La qualità di un agente dipende molto dagli **strumenti**. Pochi strumenti chiari battono tanti strumenti confusi. Ogni strumento ha un nome parlante, una **descrizione** che dice cosa fa, quando usarlo e cosa restituisce, e uno schema di input preciso.', 'An agent’s quality depends heavily on its **tools**. A few clear tools beat many confusing ones. Each tool has a telling name, a **description** saying what it does, when to use it and what it returns, and a precise input schema.'),
            C('{
  "name": "cerca_ordini",
  "description": "Cerca gli ordini di un cliente per email. Usalo quando l’utente chiede lo stato di un ordine. Restituisce al massimo 10 ordini, dal più recente, con id, data, stato e totale.",
  "input_schema": {
    "type": "object",
    "properties": {
      "email": {"type": "string", "description": "Email del cliente"},
      "stato": {"type": "string", "enum": ["tutti", "aperti", "spediti"]}
    },
    "required": ["email"]
  }
}', 'json'),
            P('I risultati devono essere **brevi e utili**: niente dump di migliaia di righe, che riempiono il contesto. In caso di errore, restituisci un messaggio che aiuti il modello a correggersi (“email non valida: usa il formato nome@dominio”).', 'Results must be **short and useful**: no dumps of thousands of lines that fill the context. On error, return a message that helps the model fix itself (“invalid email: use the name@domain format”).'),
        ], [
            Q('t1', L('Che cosa deve dire la descrizione di uno strumento?', 'What should a tool description say?'), [L('Cosa fa, quando usarlo, cosa restituisce', 'What it does, when to use it, what it returns'), L('Chi l’ha scritto', 'Who wrote it'), L('Il prezzo', 'The price'), L('Niente, basta il nome', 'Nothing, the name is enough')], 0, L('È la guida del modello.', 'It is the model’s guide.')),
            Q('t2', L('Perché i risultati devono essere brevi?', 'Why should results be short?'), [L('Per non riempire il contesto', 'So they do not fill the context'), L('Per risparmiare inchiostro', 'To save ink'), L('Per sembrare eleganti', 'To look elegant'), L('Non devono', 'They need not be')], 0, L('Il contesto è prezioso.', 'Context is precious.')),
            Q('t3', L('Che cosa restituire in caso di errore?', 'What should you return on error?'), [L('Un messaggio che aiuti a correggersi', 'A message that helps self-correction'), L('Niente', 'Nothing'), L('Un codice incomprensibile', 'An incomprehensible code'), L('Lo stack trace intero', 'The whole stack trace')], 0, L('Il modello può riprovare meglio.', 'The model can retry better.')),
        ], task('json', L('Scrivi la definizione dello strumento `prenota_sala` con una descrizione di almeno 40 caratteri e `input_schema` con `sala` e `data` obbligatori.', 'Write the definition of the tool `prenota_sala` with a description of at least 40 characters and an `input_schema` with required `sala` and `data`.'), '', [re('"name"\s*:\s*"prenota_sala"', L('Il nome', 'The name')), re('"description"\s*:\s*"[^"]{40,}"', L('Una descrizione completa', 'A full description')), re('"required"\s*:\s*\[\s*"(sala|data)"\s*,\s*"(sala|data)"\s*\]', L('Campi obbligatori', 'Required fields'))], '', "{\n  \"name\": \"prenota_sala\",\n  \"description\": \"Prenota una sala riunioni per una data. Usalo quando l’utente chiede di prenotare. Restituisce la conferma o le sale libere.\",\n  \"input_schema\": {\n    \"type\": \"object\",\n    \"properties\": {\"sala\": {\"type\": \"string\"}, \"data\": {\"type\": \"string\"}},\n    \"required\": [\"sala\", \"data\"]\n  }\n}"), [
            dMatch(pMatch(), [[L('Nome parlante', 'Telling name'), 'cerca_ordini'], [L('Descrizione', 'Description'), L('Cosa, quando, risultato', 'What, when, result')], ['enum', L('Valori ammessi', 'Allowed values')], [L('Errore utile', 'Helpful error'), L('Aiuta a correggersi', 'Helps self-correction')]], L('Strumenti ben fatti.', 'Well-made tools.')),
            dFlash(pFlash(), [[L('Pochi strumenti chiari sono meglio di tanti confusi', 'A few clear tools beat many confusing ones'), true], [L('Un risultato di 10.000 righe è ideale', 'A 10,000-line result is ideal'), false], [L('La descrizione guida la scelta del modello', 'The description guides the model’s choice'), true], [L('Il nome dello strumento non conta', 'The tool name does not matter'), false]], L('Gli attrezzi fanno l’artigiano.', 'Tools make the craftsman.')),
        ]),
        lesson('mcp', L('Model Context Protocol', 'Model Context Protocol'), [
            P('Il **Model Context Protocol** (MCP) è uno standard aperto, introdotto da Anthropic nel 2024 e oggi affidato a una fondazione indipendente, per collegare modelli e app a strumenti e dati esterni. Un **server MCP** espone strumenti (e risorse, prompt) in un formato comune; qualsiasi **client MCP** compatibile (assistenti, editor, agenti) li può usare.', 'The **Model Context Protocol** (MCP) is an open standard, introduced by Anthropic in 2024 and now entrusted to an independent foundation, for connecting models and apps to external tools and data. An **MCP server** exposes tools (and resources, prompts) in a common format; any compatible **MCP client** (assistants, editors, agents) can use them.'),
            C('from mcp.server.mcpserver import MCPServer

mcp = MCPServer("biblioteca")

@mcp.tool()
def cerca_libro(titolo: str) -> str:
    """Cerca un libro nel catalogo della biblioteca e dice se è disponibile."""
    return catalogo.cerca(titolo)

if __name__ == "__main__":
    mcp.run()', 'python'),
            P('Il vantaggio: scrivi l’integrazione **una volta** e funziona con tanti client, invece di rifarla per ogni app. Prima di installare un server MCP di terzi, controlla chi l’ha scritto e quali permessi ottiene: è codice che agisce a tuo nome.', 'The advantage: you write the integration **once** and it works with many clients, instead of redoing it for every app. Before installing a third-party MCP server, check who wrote it and what permissions it gets: it is code acting on your behalf.'),
            Fig(L(fig_agents_mcp('App host', 'assistente, editor, agente', 'file', 'leggi, cerca, scrivi', 'database', 'interrogazioni in sola lettura', 'calendario', 'eventi e promemoria', 'Un solo protocollo: ogni server funziona con ogni client compatibile.'), fig_agents_mcp('Host app', 'assistant, editor, agent', 'files', 'read, search, write', 'database', 'read-only queries', 'calendar', 'events and reminders', 'One protocol: every server works with every compatible client.')),
                L('A sinistra un’app host con dentro un client MCP; da esso partono tre collegamenti verso tre server MCP a destra: file, database e calendario, ciascuno con i suoi strumenti.', 'On the left a host app with an MCP client inside; from it three links go to three MCP servers on the right: files, database and calendar, each with its own tools.'),
                L('Il client parla MCP; ogni server espone i suoi strumenti nello stesso formato.', 'The client speaks MCP; each server exposes its tools in the same format.')),
        ], [
            Q('p1', L('Che cos’è MCP?', 'What is MCP?'), [L('Uno standard per collegare modelli a strumenti e dati', 'A standard to connect models to tools and data'), L('Un modello linguistico', 'A language model'), L('Un linguaggio di programmazione', 'A programming language'), L('Un formato di immagine', 'An image format')], 0, L('Model Context Protocol.', 'Model Context Protocol.')),
            Q('p2', L('Che cosa espone un server MCP?', 'What does an MCP server expose?'), [L('Strumenti, risorse e prompt', 'Tools, resources and prompts'), L('Solo immagini', 'Only images'), L('Password', 'Passwords'), L('Niente', 'Nothing')], 0, L('In un formato comune.', 'In a common format.')),
            Q('p3', L('Che cosa controllare prima di installare un server MCP di terzi?', 'What should you check before installing a third-party MCP server?'), [L('Chi l’ha scritto e quali permessi ottiene', 'Who wrote it and what permissions it gets'), L('Il colore del logo', 'The logo colour'), L('Niente', 'Nothing'), L('Solo il nome', 'Only the name')], 0, L('Agisce a tuo nome.', 'It acts on your behalf.')),
        ], task('python', L('Aggiungi al server `mcp` lo strumento `meteo(citta: str) -> str` con il decoratore `@mcp.tool()` e una docstring.', 'Add to the `mcp` server the tool `meteo(citta: str) -> str` with the `@mcp.tool()` decorator and a docstring.'), "from mcp.server.mcpserver import MCPServer\nmcp = MCPServer(\"meteo\")\n", [re('@mcp\.tool\s*\(\s*\)\s*\n\s*def\s+meteo\s*\(\s*citta\s*:\s*str\s*\)\s*->\s*str\s*:', L('Lo strumento è registrato', 'The tool is registered')), re('def\s+meteo[^\n]*\n\s+"""[^"]{5,}"""', L('Ha una docstring', 'It has a docstring'))], '', "@mcp.tool()\ndef meteo(citta: str) -> str:\n    \"\"\"Restituisce il meteo attuale di una città.\"\"\"\n    return previsioni(citta)"), [
            dMatch(pMatch(), [[L('Server MCP', 'MCP server'), L('Espone strumenti', 'Exposes tools')], [L('Client MCP', 'MCP client'), L('Li usa', 'Uses them')], ['@mcp.tool()', L('Registra uno strumento', 'Registers a tool')], ['Docstring', L('Diventa la descrizione', 'Becomes the description')]], L('MCP in breve.', 'MCP in short.')),
            dFlash(pFlash(), [[L('MCP è uno standard aperto', 'MCP is an open standard'), true], [L('Un server MCP funziona con un solo client', 'An MCP server works with only one client'), false], [L('Un server MCP di terzi può agire a tuo nome', 'A third-party MCP server can act on your behalf'), true], [L('MCP è un modello di immagini', 'MCP is an image model'), false]], L('Un’integrazione, tanti client.', 'One integration, many clients.')),
        ]),
        lesson('safety', L('Sicurezza ed evaluation', 'Safety and evaluation'), [
            P('Un agente con strumenti può fare danni veri: cancellare file, mandare email, spendere soldi. Le regole: **minimo privilegio** (solo gli strumenti necessari), **ambiente isolato** per eseguire codice, **conferma umana** per le azioni irreversibili, **limiti** di passi e spesa, e **log** di tutto quello che fa.', 'An agent with tools can do real damage: delete files, send email, spend money. The rules: **least privilege** (only the tools needed), an **isolated environment** to run code, **human confirmation** for irreversible actions, **limits** on steps and spending, and **logs** of everything it does.'),
            P('Tutto quello che l’agente legge (pagine web, email, documenti) può contenere **prompt injection**: trattalo come dato, mai come istruzione. Per valutare un agente servono compiti realistici con un risultato verificabile (i test passano? il file giusto è cambiato?), eseguiti più volte perché il comportamento varia.', 'Everything the agent reads (web pages, emails, documents) can contain **prompt injection**: treat it as data, never as instructions. To evaluate an agent you need realistic tasks with a verifiable result (do the tests pass? did the right file change?), run several times because behaviour varies.'),
            Tip('Chiediti sempre: se l’agente sbaglia nel modo peggiore possibile, che cosa succede? Se la risposta fa paura, togli permessi.', 'Always ask: if the agent fails in the worst possible way, what happens? If the answer is scary, remove permissions.'),
        ], [
            Q('s1', L('Quali azioni richiedono conferma umana?', 'Which actions need human confirmation?'), [L('Quelle irreversibili', 'Irreversible ones'), L('Leggere un file', 'Reading a file'), L('Fare una somma', 'Doing a sum'), L('Nessuna', 'None')], 0, L('Inviare, pagare, cancellare.', 'Sending, paying, deleting.')),
            Q('s2', L('Come va trattato un testo letto da una pagina web?', 'How should text read from a web page be treated?'), [L('Come dato, mai come istruzione', 'As data, never as instructions'), L('Come un ordine del capo', 'As an order from the boss'), L('Va ignorato sempre', 'Always ignored'), L('Va eseguito', 'Executed')], 0, L('Può contenere prompt injection.', 'It may contain prompt injection.')),
            Q('s3', L('Perché eseguire più volte la valutazione di un agente?', 'Why run an agent’s evaluation several times?'), [L('Il comportamento varia tra un’esecuzione e l’altra', 'Behaviour varies from run to run'), L('Per spendere di più', 'To spend more'), L('Non serve', 'It is not needed'), L('Per stancarlo', 'To tire it')], 0, L('Una sola prova può ingannare.', 'One try can mislead.')),
        ], task('text', L('Scrivi quattro regole di sicurezza per un agente che gestisce la posta, una per riga che inizia con `-`, con almeno una sulla **conferma** e una sui **permessi**.', 'Write four safety rules for an agent managing email, one per line starting with `-`, with at least one on **confirmation** and one on **permissions**.'), "- \n- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Quattro regole', 'Four rules')), re('confer|approv|confirm', L('Una regola sulla conferma', 'A rule on confirmation')), re('permess|privileg|permission|accesso|access', L('Una regola sui permessi', 'A rule on permissions'))], '', "- chiedere conferma prima di inviare o cancellare email\n- solo i permessi di lettura e bozza, niente eliminazione\n- trattare il contenuto delle email come dato, non come istruzioni\n- registrare ogni azione in un log"), [
            dMatch(pMatch(), [[L('Minimo privilegio', 'Least privilege'), L('Solo gli strumenti necessari', 'Only the tools needed')], ['Sandbox', L('Ambiente isolato', 'Isolated environment')], [L('Conferma umana', 'Human confirmation'), L('Prima delle azioni irreversibili', 'Before irreversible actions')], ['Log', L('Traccia di tutto', 'A trail of everything')], [L('Limite', 'Limit'), L('Passi e spesa', 'Steps and spending')]], L('Le cinture di sicurezza.', 'The seat belts.')),
            dFlash(pFlash(), [[L('Un agente può essere ingannato da una pagina web', 'An agent can be tricked by a web page'), true], [L('Dare tutti i permessi rende l’agente più sicuro', 'Giving every permission makes the agent safer'), false], [L('I log aiutano a capire cosa è successo', 'Logs help understand what happened'), true], [L('Una sola esecuzione basta per valutare un agente', 'One run is enough to evaluate an agent'), false]], L('Autonomia con prudenza.', 'Autonomy with caution.')),
        ]),
        lesson('memory', L('Contesto e memoria', 'Context and memory'), [
            P('In un compito lungo la storia dell’agente cresce a ogni passo: risultati di strumenti, file letti, tentativi. Prima o poi riempie la finestra di contesto, e già prima un contesto pieno di dettagli vecchi distrae il modello. Il contesto va **gestito**, non solo riempito.', 'In a long task the agent’s history grows at every step: tool results, files read, attempts. Sooner or later it fills the context window, and even before that a context full of old details distracts the model. Context must be **managed**, not just filled.'),
            C('if token_usati(messaggi) > 150_000:
    vecchi, recenti = taglia_in_punto_pulito(messaggi, tieni=6)   # mai tra tool_use e tool_result
    riassunto = riassumi(vecchi)          # obiettivo, decisioni, file toccati, cosa manca
    messaggi = [{"role": "user", "content": f"Riassunto del lavoro finora:\n{riassunto}"}] + recenti', 'python'),
            P('Tecniche comuni: **compattare** la storia vecchia in un riassunto (alcune API lo fanno lato server), **togliere** i risultati di strumenti ormai inutili, e dare all’agente una **memoria esterna**, come un file di note o uno strumento di memoria in cui scrive progressi e decisioni da rileggere in seguito, anche in una sessione nuova.', 'Common techniques: **compacting** old history into a summary (some APIs do it server-side), **clearing** tool results that are no longer useful, and giving the agent an **external memory**, such as a notes file or a memory tool where it writes progress and decisions to reread later, even in a new session.'),
        ], [
            Q('c1', L('Perché un contesto pieno di dettagli vecchi è un problema anche prima del limite?', 'Why is a context full of old details a problem even before the limit?'), [L('Perché rende il modello più economico', 'Because it makes the model cheaper'), L('Perché il modello smette di usare strumenti', 'Because the model stops using tools'), L('Non è un problema finché c’è spazio', 'It is no problem while there is room'), L('Distrae il modello e costa token', 'It distracts the model and costs tokens')], 3, L('Più testo non vuol dire più attenzione.', 'More text does not mean more attention.')),
            Q('c2', L('Che cosa conviene tenere nel riassunto di una compattazione?', 'What should a compaction summary keep?'), [L('Obiettivo, decisioni prese e cosa resta da fare', 'Goal, decisions taken and what is left to do'), L('Ogni risultato di strumento parola per parola', 'Every tool result word for word'), L('Solo l’ultimo messaggio dell’utente', 'Only the user’s last message'), L('Niente: si riparte da zero', 'Nothing: start from scratch')], 0, L('L’essenziale per continuare.', 'The essentials to carry on.')),
            Q('c3', L('A che cosa serve una memoria esterna per un agente?', 'What is an external memory for an agent?'), [L('A ingrandire la finestra di contesto del modello', 'To enlarge the model’s context window'), L('A conservare progressi e decisioni da rileggere più tardi', 'To keep progress and decisions to reread later'), L('A cancellare la storia ogni dieci messaggi', 'To delete the history every ten messages'), L('A nascondere i passi all’utente', 'To hide the steps from the user')], 1, L('Anche tra una sessione e l’altra.', 'Even across sessions.')),
        ], task('text', L('Scrivi le quattro voci che metteresti nel riassunto di un agente che sta sistemando un sito, una per riga che inizia con `-`, con almeno l’**obiettivo** e **cosa manca**.', 'Write the four items you would put in the summary of an agent fixing a website, one per line starting with `-`, with at least the **goal** and **what is left**.'), "- \n- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Quattro voci', 'Four items')), re('obiettiv|goal|scopo|aim', L('C’è l’obiettivo', 'The goal is there')), re('manca|resta|da fare|prossim|left|todo|to do|next|remaining', L('C’è cosa manca', 'What is left is there'))], '', "- obiettivo: correggere i link rotti del sito\n- fatto: sistemati 12 link nelle pagine del blog\n- decisione: i link esterni morti vengono tolti, non sostituiti\n- da fare: controllare le pagine dei prodotti"), [
            dMatch(pMatch(), [[L('Compattazione', 'Compaction'), L('Riassume la storia vecchia', 'Summarises old history')], [L('Pulizia dei risultati', 'Clearing results'), L('Toglie output ormai inutili', 'Removes outputs no longer useful')], [L('Memoria esterna', 'External memory'), L('Note da rileggere', 'Notes to reread')], [L('Punto pulito', 'Clean cut'), L('Mai tra tool_use e tool_result', 'Never between tool_use and tool_result')]], L('Gestire il contesto.', 'Managing context.')),
            dFlash(pFlash(), [[L('La storia di un agente cresce a ogni passo', 'An agent’s history grows at every step'), true], [L('Più contesto rende il modello sempre più preciso', 'More context always makes the model more precise'), false], [L('Un file di note può fare da memoria tra sessioni', 'A notes file can act as memory across sessions'), true], [L('Si può tagliare la storia tra un tool_use e il suo tool_result', 'You can cut the history between a tool_use and its tool_result'), false]], L('Ricordare l’essenziale.', 'Remember the essentials.')),
        ]),
        lesson('multi-agent', L('Più agenti insieme', 'Several agents together'), [
            P('In un sistema **multi-agente** un **orchestratore** divide il compito e affida le parti a **sotto-agenti**, ognuno con il suo contesto pulito e i suoi strumenti. Funziona bene quando il lavoro si divide in parti **indipendenti** da fare in parallelo, per esempio una ricerca su molte fonti: ogni sotto-agente legge tanto e restituisce solo una sintesi breve.', 'In a **multi-agent** system an **orchestrator** splits the task and hands the parts to **sub-agents**, each with its own clean context and tools. It works well when the work splits into **independent** parts to do in parallel, for example research over many sources: each sub-agent reads a lot and returns only a short summary.'),
            Fig(L(fig_agents_multi('orchestratore', 'sotto-agente', 'contesto proprio', 'legge molto', 'unisce le sintesi brevi', 'divide il compito'), fig_agents_multi('orchestrator', 'sub-agent', 'own context', 'reads a lot', 'merges the short summaries', 'splits the task')),
                L('In alto un orchestratore manda tre frecce a tre sotto-agenti, ciascuno con il proprio contesto, che leggono molto. Le loro uscite confluiscono in un riquadro verde in basso che unisce le sintesi brevi.', 'At the top an orchestrator sends three arrows to three sub-agents, each with its own context, who read a lot. Their outputs flow into a green box at the bottom that merges the short summaries.'),
                L('Ogni sotto-agente consuma molti token per restituirne pochi.', 'Each sub-agent spends many tokens to return a few.')),
            C('import asyncio

async def ricerca(domanda):
    sotto_domande = await orchestratore(f"Dividi in 3 sotto-domande indipendenti: {domanda}")
    sintesi = await asyncio.gather(*(sotto_agente(d) for d in sotto_domande))
    return await orchestratore(f"Unisci queste sintesi e cita le fonti:\n{sintesi}")', 'python'),
            P('Il conto però sale: più agenti, molti più token. E se le parti dipendono l’una dall’altra (scrivere codice che deve combaciare), gli agenti si pestano i piedi. Dai a ogni sotto-agente un compito chiaro, cosa restituire e in che formato; e chiediti sempre se un solo agente ben fatto non basterebbe.', 'The bill goes up, though: more agents, many more tokens. And if the parts depend on each other (writing code that must fit together), the agents get in each other’s way. Give each sub-agent a clear task, what to return and in what format; and always ask whether a single well-built agent would do.'),
        ], [
            Q('a1', L('Quando conviene un sistema multi-agente?', 'When is a multi-agent system worth it?'), [L('Per ogni compito, anche il più semplice', 'For every task, even the simplest'), L('Quando le parti dipendono strettamente l’una dall’altra', 'When the parts depend tightly on each other'), L('Quando il lavoro si divide in parti indipendenti e parallele', 'When the work splits into independent, parallel parts'), L('Quando si vuole spendere meno token', 'When you want to spend fewer tokens')], 2, L('Ricerca su molte fonti, per esempio.', 'Research over many sources, for example.')),
            Q('a2', L('Perché ogni sotto-agente restituisce solo una sintesi?', 'Why does each sub-agent return only a summary?'), [L('Per non riempire il contesto dell’orchestratore', 'So as not to fill the orchestrator’s context'), L('Perché non può leggere documenti lunghi', 'Because it cannot read long documents'), L('Per nascondere le fonti all’utente', 'To hide the sources from the user'), L('Perché lo impone il protocollo MCP', 'Because the MCP protocol requires it')], 0, L('Legge tanto, riporta poco.', 'It reads a lot, reports little.')),
            Q('a3', L('Qual è il costo principale di più agenti?', 'What is the main cost of several agents?'), [L('Le risposte diventano meno precise', 'Answers become less precise'), L('Molti più token consumati', 'Many more tokens used'), L('Non si possono usare strumenti', 'Tools cannot be used'), L('Serve un modello diverso per ognuno', 'Each needs a different model')], 1, L('Ogni agente ha il suo contesto da pagare.', 'Each agent has its own context to pay for.')),
        ], task('python', L('Completa `ricerca`: lancia in parallelo `sotto_agente(d)` per ogni `d` in `sotto_domande` con `asyncio.gather` e salva il risultato in `sintesi`.', 'Complete `ricerca`: run `sotto_agente(d)` in parallel for each `d` in `sotto_domande` with `asyncio.gather` and store the result in `sintesi`.'), "import asyncio\n\nasync def ricerca(domanda):\n    sotto_domande = await orchestratore(f\"Dividi in sotto-domande: {domanda}\")\n    ", [re('sintesi\s*=\s*await\s+asyncio\.gather\s*\(\s*\*\s*\(?\s*\[?\s*sotto_agente\s*\(\s*(\w+)\s*\)\s+for\s+\1\s+in\s+sotto_domande', L('Sotto-agenti in parallelo', 'Sub-agents in parallel'))], '', "sintesi = await asyncio.gather(*(sotto_agente(d) for d in sotto_domande))"), [
            dOrder(pSort(), [L('L’orchestratore divide il compito', 'The orchestrator splits the task'), L('I sotto-agenti lavorano in parallelo', 'Sub-agents work in parallel'), L('Ognuno restituisce una sintesi breve', 'Each returns a short summary'), L('L’orchestratore unisce i risultati', 'The orchestrator merges the results')], L('Dividere, lavorare, unire.', 'Split, work, merge.')),
            dFlash(pFlash(), [[L('Ogni sotto-agente può avere un contesto pulito', 'Each sub-agent can have a clean context'), true], [L('Più agenti costano sempre meno di uno', 'More agents always cost less than one'), false], [L('Le parti indipendenti si prestano al parallelo', 'Independent parts lend themselves to parallel work'), true], [L('Un sotto-agente non ha bisogno di istruzioni chiare', 'A sub-agent needs no clear instructions'), false]], L('Squadra sì, ma con criterio.', 'A team, but with judgement.')),
        ]),
        lesson('mcp-practice', L('MCP in pratica', 'MCP in practice'), [
            P('Un server MCP può girare in due modi. Con il trasporto **stdio** il client lo avvia come processo locale e parla con lui da standard input e output: ideale per strumenti sul tuo computer. Con lo **Streamable HTTP** il server sta in rete e serve più utenti; in questo caso serve un’**autorizzazione**, di solito con OAuth, per sapere chi chiede che cosa.', 'An MCP server can run in two ways. With the **stdio** transport the client launches it as a local process and talks to it through standard input and output: ideal for tools on your computer. With **Streamable HTTP** the server lives on the network and serves many users; then you need **authorisation**, usually with OAuth, to know who is asking for what.'),
            C('from mcp.server.mcpserver import MCPServer

mcp = MCPServer("biblioteca")

@mcp.resource("catalogo://generi")
def generi() -> str:
    """Elenco dei generi presenti nel catalogo."""
    return "giallo, fantasy, saggistica, ragazzi"

@mcp.prompt()
def consiglio(genere: str) -> str:
    return f"Consiglia tre libri del genere {genere} presenti nel catalogo."

if __name__ == "__main__":
    mcp.run()          # stdio; in rete: mcp.run(transport="streamable-http")', 'python'),
            P('Oltre agli **strumenti** (azioni scelte dal modello), un server può offrire **risorse** (dati da leggere, identificati da un URI) e **prompt** (modelli di richiesta pronti, scelti dall’utente). Il client si configura indicando come avviare o raggiungere ogni server; il formato preciso dipende dal client.', 'Besides **tools** (actions chosen by the model), a server can offer **resources** (data to read, identified by a URI) and **prompts** (ready request templates, chosen by the user). The client is configured with how to launch or reach each server; the exact format depends on the client.'),
        ], [
            Q('p1', L('Quando si usa il trasporto stdio?', 'When is the stdio transport used?'), [L('Per un server in rete con molti utenti', 'For a networked server with many users'), L('Per inviare email agli utenti', 'For sending emails to users'), L('Solo per i server scritti in C', 'Only for servers written in C'), L('Per un server avviato come processo locale dal client', 'For a server launched as a local process by the client')], 3, L('Parla da standard input e output.', 'It talks via standard input and output.')),
            Q('p2', L('Che cosa serve a un server MCP remoto con molti utenti?', 'What does a remote MCP server with many users need?'), [L('Un’autorizzazione, di solito con OAuth', 'Authorisation, usually with OAuth'), L('Un modello linguistico installato sul server', 'A language model installed on the server'), L('Un file GGUF', 'A GGUF file'), L('Nessuna configurazione particolare', 'No particular configuration')], 0, L('Sapere chi chiede che cosa.', 'Knowing who asks for what.')),
            Q('p3', L('Che differenza c’è tra una risorsa e uno strumento MCP?', 'What is the difference between an MCP resource and tool?'), [L('Nessuna, sono sinonimi', 'None, they are synonyms'), L('La risorsa è un dato da leggere, lo strumento un’azione', 'A resource is data to read, a tool is an action'), L('La risorsa costa di più', 'A resource costs more'), L('Lo strumento funziona solo in stdio', 'A tool only works over stdio')], 1, L('Le risorse hanno un URI.', 'Resources have a URI.')),
        ], task('python', L('Aggiungi al server `mcp` una risorsa `orari://biblioteca` con il decoratore `@mcp.resource("orari://biblioteca")`, una funzione `orari() -> str` e una docstring.', 'Add to the `mcp` server a resource `orari://biblioteca` with the decorator `@mcp.resource("orari://biblioteca")`, a function `orari() -> str` and a docstring.'), "from mcp.server.mcpserver import MCPServer\nmcp = MCPServer(\"biblioteca\")\n", [re('@mcp\.resource\s*\(\s*["\']orari://biblioteca["\']\s*\)\s*\n\s*def\s+orari\s*\(\s*\)\s*->\s*str\s*:', L('La risorsa è registrata', 'The resource is registered')), re('def\s+orari[^\n]*\n\s+"""[^"]{5,}"""', L('Ha una docstring', 'It has a docstring'))], '', "@mcp.resource(\"orari://biblioteca\")\ndef orari() -> str:\n    \"\"\"Orari di apertura della biblioteca.\"\"\"\n    return \"lun-ven 9-19, sab 9-13\""), [
            dMatch(pMatch(), [['stdio', L('Processo locale', 'Local process')], ['Streamable HTTP', L('Server in rete', 'Networked server')], [L('Risorsa', 'Resource'), L('Dato da leggere con un URI', 'Data to read via a URI')], ['Prompt', L('Modello di richiesta per l’utente', 'Request template for the user')], ['OAuth', L('Chi può fare che cosa', 'Who may do what')]], L('I pezzi di MCP.', 'The pieces of MCP.')),
            dFlash(pFlash(), [[L('Un server MCP può offrire risorse oltre agli strumenti', 'An MCP server can offer resources besides tools'), true], [L('Un server remoto non ha bisogno di autorizzazione', 'A remote server needs no authorisation'), false], [L('Con stdio il client avvia il server in locale', 'With stdio the client starts the server locally'), true], [L('Tutti i client usano lo stesso file di configurazione', 'All clients use the same configuration file'), false]], L('Dal protocollo al progetto.', 'From protocol to project.')),
        ]),
